COMMENT = "auto";
/MN
   1:  UFRAME_NUM=1 ;
   2:  UTOOL_NUM=1 ;
   3:  !Pick from conveyor and place on fixture A ;
   4:  !Approach from conveyor approach (PR[6]) and fixture A approach (PR[7]) ;
   5:  !Use gripper RO[1] to close and RO[2] to open ;
   6:  !Gentle handling: increased settle to 1.0s ;
   7:  J PR[1:home] 100% FINE ;
   8:  L PR[6:conveyor approach] 100mm/sec CNT50 ;
   9:  L PR[5:conveyor pick] 50mm/sec FINE ;
  10:  RO[1:gripper close]=ON ;
