  13:  L PR[7:fixture A approach] 100mm/sec CNT50 ;
  14:  L PR[8:fixture A place] 50mm/sec FINE ;
  15:  RO[1:gripper close]=OFF ;
  16:  RO[2:gripper open]=ON ;
  17:  WAIT .20(sec) ;
  18:  J PR[1:home] 100% FINE ;
/POS
/END

